mapper.select:
SELECT aa.id AS id, aa.uid AS uid, COALESCE(NULLIF(TRIM(ui.realname), ''), NULLIF(TRIM(ui.username), ''), aa.uid) AS username, aa.title AS title, aa.status AS status, (UNIX_TIMESTAMP(aa.gmt_create) * 1000) AS submitTime FROM achievement_apply aa LEFT JOIN user_info ui ON ui.uid = aa.uid
AND aa.status = #{status}
AND ui.college_id = #{collegeId}
AND ( aa.uid LIKE CONCAT('%', #{keyword}, '%') OR aa.title LIKE CONCAT('%', #{keyword}, '%') OR ui.username LIKE CONCAT('%', #{keyword}, '%') OR ui.realname LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY aa.gmt_create DESC, aa.id DESC
